import{_ as s,C as n,o as e,c as d,j as i,E as r,a as l,a3 as o}from"./chunks/framework.C6R8kWFE.js";const S=JSON.parse(`{"title":"13-dars (Mentor). O'yin uchun ikonka va spraytlar yaratish (3-qism): Sprayt sheet (atlas) tayyorlash va optimallashtirish","description":"","frontmatter":{"title":"13-dars (Mentor). O'yin uchun ikonka va spraytlar yaratish (3-qism): Sprayt sheet (atlas) tayyorlash va optimallashtirish","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (Game)","link":"/mentor/9-sinf-game/"},"week":{"n":5,"link":"/mentor/9-sinf-game/hafta-05/"},"g":13,"title":"O'yin uchun ikonka va spraytlar yaratish (3-qism): Sprayt sheet (atlas) tayyorlash va optimallashtirish","lead":"Qahramoningiz yurishi uchun 6 ta rasm kerak, tangalar, zelyelar, kalitlar uchun yana o'nlab. Ularni bitta tartibli faylga yig'sak, o'yin tezroq ishlaydi. Bugun shu faylni — sprayt sheet'ni yaratamiz.","slide":"/slaydlar/9-sinf-game/hafta-05/dars-1.html","test":"/slaydlar/9-sinf-game/hafta-05/dars-1-test.html","student_link":"/9-sinf-game/hafta-05/dars-1","tabs":[{"g":13,"link":"/mentor/9-sinf-game/hafta-05/dars-1","current":true},{"g":14,"link":"/mentor/9-sinf-game/hafta-05/dars-2","current":false},{"g":15,"link":"/mentor/9-sinf-game/hafta-05/dars-3","current":false}],"prev":null,"next":{"g":14,"title":"UI dizayn: tugmalar, menyular, HUD (1-qism): Tugmalar turlari, holatlari (Normal, Hover, Pressed)","link":"/mentor/9-sinf-game/hafta-05/dars-2"}}},"headers":[],"relativePath":"mentor/9-sinf-game/hafta-05/dars-1.md","filePath":"mentor/9-sinf-game/hafta-05/dars-1.md"}`),h={name:"mentor/9-sinf-game/hafta-05/dars-1.md"},k={class:"blk"},m={id:"dars-rejasi",tabindex:"-1"},y={class:"blk"},g={id:"mentor-konspekti",tabindex:"-1"},u={class:"blk"},b={id:"amaliy-topshiriqlar-va-yechimlar",tabindex:"-1"},q={class:"blk"},p={id:"tezkor-nazorat-savollari",tabindex:"-1"},c={class:"blk"},f={id:"keng-tarqalgan-xatolar-va-ularning-oldini-olish",tabindex:"-1"};function _(v,a,x,j,z,P){const t=n("Icon");return e(),d("div",null,[i("div",k,[i("h2",m,[r(t,{name:"file-text"}),a[0]||(a[0]=l(" Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> Dars rejasi"'},"​",-1))]),a[2]||(a[2]=o("<ul><li><strong>Darsning maqsadi:</strong> O&#39;quvchilarga animatsiya kadrlarini va o&#39;yin obyektlarini bitta PNG faylga — sprayt sheet (atlas) ko&#39;rinishiga yig&#39;ishni o&#39;rgatish; nega o&#39;yin dvijoklari (Unity, Godot, Unreal) atlasni afzal ko&#39;rishini (draw call, xotira, yuklanish) tushuntirish; Photoshop&#39;da teng katakli to&#39;r bo&#39;yicha sheet tayyorlash, nomlash va eksport qilishni amalda bajarish.</li><li><strong>Kutiladigan natija:</strong> O&#39;quvchilar 12-darsdagi qahramon kadrlaridan va obyekt spraytlaridan 2 ta sheet tayyorlaydi: animatsiya sheet (bir qator, teng kataklar) va obyektlar atlasi (ikonka + sprayt); fayl hajmini va ranglar sonini optimallashtiradi; shaffof PNG qilib eksport qiladi va kadr o&#39;lchamini (masalan, 32×32) hujjatga yozib qo&#39;yadi.</li><li><strong>Vaqt taqsimoti:</strong><ul><li>Takrorlash (sprayt bosqichlari, idle animatsiya): 10 daqiqa</li><li>Yangi mavzu: sprayt sheet va atlas tushunchasi, nega kerak: 15 daqiqa</li><li>Sheet tuzilishi: katak, qator, padding, tartib: 10 daqiqa</li><li>Amaliyot: Photoshop&#39;da animatsiya sheet yig&#39;ish: 25 daqiqa</li><li>Optimallashtirish va eksport, atlas tuzish: 15 daqiqa</li><li>Xulosa: 5 daqiqa</li></ul></li></ul><blockquote><p>Manba: o&#39;quv qo&#39;llanma — 2.3-bo&#39;lim («qahramonning yurishi, sakrashi kabi animatsiyalar sprat-sheet ko&#39;rinishida PNG bilan yaratiladi. O&#39;yin dvijoklari (Unity, Godot, Unreal) PNG-ni juda yaxshi qo&#39;llab-quvvatlaydi»), 2.4-bo&#39;lim, 8-bosqich («Animatsiya yoki turli holatlar bo&#39;lsa, alohida frame yoki sprite sheet tayyorlanadi»), 7-bob («Draw call sonini kamaytirish uchun sprite atlaslaridan foydalaning»). Photoshop&#39;dagi amaliy usullar (Canvas Size, Guides, Trim) — darsni boyituvchi amaliy qism; hujjatda batafsil qadamlar yo&#39;q.</p></blockquote><hr>",3))]),i("div",y,[i("h2",g,[r(t,{name:"file-text"}),a[3]||(a[3]=l(" Mentor konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#mentor-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> Mentor konspekti"'},"​",-1))]),a[5]||(a[5]=o('<h3 id="_1-sprayt-sheet-nima" tabindex="-1">1. Sprayt sheet nima? <a class="header-anchor" href="#_1-sprayt-sheet-nima" aria-label="Permalink to &quot;1. Sprayt sheet nima?&quot;">​</a></h3><p><strong>Sprayt sheet</strong> — bir nechta sprayt yoki animatsiya kadri bitta rasm faylida (odatda shaffof PNG) to&#39;r ko&#39;rinishida joylashgan fayl. O&#39;yin dvijogi kerakli kadrni shu rasmdan «kesib» oladi.</p><ul><li><strong>Animatsiya sheet:</strong> bitta harakatning kadrlari ketma-ket (idle 2 kadr, yurish 4–6 kadr, sakrash 3 kadr). Odatda bitta qator = bitta animatsiya.</li><li><strong>Atlas (texture atlas):</strong> turli spraytlar va ikonkalar bitta katta rasmda (tanga, zelye, kalit, jon belgisi, tugma ikonkalari).</li></ul><p>Hayotiy o&#39;xshatish: albom varaqlaridagi fotosuratlar. 20 ta alohida rasmni 20 marta qidirgandan ko&#39;ra, bitta albomni ochib kerakli sahifani olish tezroq.</p><h3 id="_2-nega-kerak" tabindex="-1">2. Nega kerak? <a class="header-anchor" href="#_2-nega-kerak" aria-label="Permalink to &quot;2. Nega kerak?&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Muammo (alohida fayllar)</th><th>Sheet/atlas bilan</th></tr></thead><tbody><tr><td>Har rasm uchun alohida yuklash</td><td>bitta fayl bir marta yuklanadi</td></tr><tr><td>Har rasm uchun alohida <strong>draw call</strong> (videokartaga chizish buyrug&#39;i)</td><td>bir xil atlasdagi spraytlar birga chiziladi — draw call kamayadi</td></tr><tr><td>Yuzlab mayda fayllar — tartibsizlik</td><td>bitta tartibli fayl, kadrlar ketma-ket</td></tr><tr><td>Animatsiya kadrlari aralashib ketadi</td><td>qator va ustun bo&#39;yicha aniq tartib</td></tr></tbody></table><p>O&#39;quv qo&#39;llanmadagi tavsiya: <em>«Draw call sonini kamaytirish uchun sprite atlaslaridan foydalaning»</em> — ayniqsa mobil qurilmalarda.</p><h3 id="_3-sheet-tuzilishi" tabindex="-1">3. Sheet tuzilishi <a class="header-anchor" href="#_3-sheet-tuzilishi" aria-label="Permalink to &quot;3. Sheet tuzilishi&quot;">​</a></h3><ul><li><strong>Katak (cell/frame):</strong> har kadr uchun bir xil o&#39;lcham, masalan 32×32 px. Hamma kataklar teng — dvijok to&#39;rni avtomatik kesadi (Unity&#39;da <em>Grid By Cell Size</em>).</li><li><strong>Qator:</strong> bitta animatsiya. 1-qator — idle, 2-qator — yurish, 3-qator — sakrash.</li><li><strong>Padding (oraliq):</strong> kataklar orasida 1–2 px bo&#39;sh joy — qo&#39;shni kadr rangi «oqib» kirmasligi uchun (bleeding).</li><li><strong>Tayanch nuqta (pivot):</strong> barcha kadrlarda qahramon oyog&#39;i bir xil balandlikda — aks holda animatsiya «sakraydi».</li><li><strong>Hajm:</strong> 4 kadr × 32 px = 128 px kenglik. Ko&#39;p dvijoklar uchun 2 ning darajalari (64, 128, 256, 512) qulay.</li></ul><h3 id="_4-photoshop-da-animatsiya-sheet-yig-ish" tabindex="-1">4. Photoshop&#39;da animatsiya sheet yig&#39;ish <a class="header-anchor" href="#_4-photoshop-da-animatsiya-sheet-yig-ish" aria-label="Permalink to &quot;4. Photoshop&#39;da animatsiya sheet yig&#39;ish&quot;">​</a></h3><ol><li>Yangi hujjat: <strong>128×32 px</strong> (4 kadr × 32), Background — <strong>Transparent</strong>.</li><li><strong>View → New Guide Layout:</strong> Columns 4, Gutter 0 — har 32 px da yo&#39;naltiruvchi chiziq.</li><li>12-darsdagi <code>.psd</code> dan har kadr guruhini nusxalab (<code>Ctrl + J</code>, so&#39;ng sudrab), har biri o&#39;z katagiga <strong>Move Tool (V)</strong> bilan joylashtiriladi. Snap yoqilgan bo&#39;lsin (View → Snap).</li><li>Qatlamlar nomi: <code>kadr_01</code>, <code>kadr_02</code>... guruh nomi: <code>idle</code>.</li><li>Tekshirish: oyoq chizig&#39;i barcha kadrlarda bir xil y koordinatada.</li><li><strong>File → Export → Export As:</strong> PNG, Transparency ✓, 100% — dvijok uchun. Nomi: <code>qahramon_idle_sheet_32x32.png</code> (kadr o&#39;lchami nomda).</li></ol><h3 id="_5-obyektlar-atlasi" tabindex="-1">5. Obyektlar atlasi <a class="header-anchor" href="#_5-obyektlar-atlasi" aria-label="Permalink to &quot;5. Obyektlar atlasi&quot;">​</a></h3><ul><li>Hujjat <strong>64×64 px</strong> (16×16 kataklar, 4×4 = 16 o&#39;rin) yoki 128×128 px.</li><li>Tanga, zelye, kalit, jon belgisi va 11-dars ikonkalari bir uslubda joylashtiriladi.</li><li>Bo&#39;sh kataklar zaxira uchun qoldiriladi — yangi buyum qo&#39;shilganda atlas o&#39;lchami o&#39;zgarmaydi.</li><li>Yonma-yon: o&#39;xshash narsalar bir qatorda (pullar, zelyelar, kalitlar).</li></ul><h3 id="_6-optimallashtirish" tabindex="-1">6. Optimallashtirish <a class="header-anchor" href="#_6-optimallashtirish" aria-label="Permalink to &quot;6. Optimallashtirish&quot;">​</a></h3><ul><li><strong>Kerakmas bo&#39;sh joyni kesish:</strong> kataklar ichida qahramon atrofidagi juda katta bo&#39;shliq — kadr o&#39;lchamini kichraytiring (lekin hammasi bir xil bo&#39;lsin).</li><li><strong>Ranglar soni:</strong> cheklangan palitra (16–32 rang) — fayl kichik, uslub yaxlit.</li><li><strong>Nusxa kadrlarni olib tashlash:</strong> bir xil ikki kadr bo&#39;lsa, birini qoldiring, dvijokda kadr vaqti uzaytiriladi.</li><li><strong>To&#39;g&#39;ri format:</strong> sheet — PNG (shaffoflik, sifat yo&#39;qotmaydi). JPG — yo&#39;q (shaffoflik yo&#39;q, siqishda artefaktlar). GIF — faqat namoyish uchun.</li><li><strong>Masshtab:</strong> dvijokka 100% (asl o&#39;lcham) beriladi, kattalashtirishni dvijokning o&#39;zi qiladi (Filter: Point/Nearest).</li><li><strong>Nomlash:</strong> <code>obyekt_holat_sheet_WxH.png</code> — jamoada hamma tushunadi.</li></ul><h3 id="_7-dvijokda-nima-bo-ladi-qisqa-namoyish-so-z-bilan" tabindex="-1">7. Dvijokda nima bo&#39;ladi (qisqa namoyish, so&#39;z bilan) <a class="header-anchor" href="#_7-dvijokda-nima-bo-ladi-qisqa-namoyish-so-z-bilan" aria-label="Permalink to &quot;7. Dvijokda nima bo&#39;ladi (qisqa namoyish, so&#39;z bilan)&quot;">​</a></h3><p>Unity&#39;da PNG import qilinadi → Sprite Mode: <strong>Multiple</strong> → Sprite Editor → Slice → <em>Grid By Cell Size</em> 32×32 → kadrlar <code>qahramon_idle_0</code>, <code>_1</code>... bo&#39;lib ajraladi. Bu Unity bo&#39;limida (keyinroq) amalda o&#39;tiladi; bugun faqat «nega to&#39;g&#39;ri katak muhim» ekanini ko&#39;rsating.</p><hr>',18))]),i("div",u,[i("h2",b,[r(t,{name:"file-text"}),a[6]||(a[6]=l(" Amaliy topshiriqlar va yechimlar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#amaliy-topshiriqlar-va-yechimlar","aria-label":'Permalink to "<Icon name="file-text" /> Amaliy topshiriqlar va yechimlar"'},"​",-1))]),a[8]||(a[8]=o('<h3 id="_1-topshiriq-sheet-hisobi-oson" tabindex="-1">1-topshiriq. Sheet hisobi (oson) <a class="header-anchor" href="#_1-topshiriq-sheet-hisobi-oson" aria-label="Permalink to &quot;1-topshiriq. Sheet hisobi (oson)&quot;">​</a></h3><p>Qahramon kadri 32×32 px. Yurish animatsiyasi 6 kadrdan iborat va bir qatorda joylashadi. Sheet o&#39;lchami qancha bo&#39;ladi? Agar idle (2 kadr) va sakrash (3 kadr) ham alohida qatorlarga qo&#39;shilsa-chi?</p><p><strong>Yechim:</strong> Bir qator: 6 × 32 = <strong>192×32 px</strong>. Uch qator (eng uzun qator 6 kadr): kenglik 192 px, balandlik 3 × 32 = 96 px → <strong>192×96 px</strong>. Bo&#39;sh kataklar (idle qatorida 4 ta, sakrashda 3 ta) shaffof qoladi.</p><h3 id="_2-topshiriq-idle-sheet-oson" tabindex="-1">2-topshiriq. Idle sheet (oson) <a class="header-anchor" href="#_2-topshiriq-idle-sheet-oson" aria-label="Permalink to &quot;2-topshiriq. Idle sheet (oson)&quot;">​</a></h3><p>12-darsdagi 2 kadrli idle animatsiyadan 64×32 px sheet tayyorlang.</p><p><strong>Yechim:</strong> File → New 64×32, Transparent → View → New Guide Layout (Columns 2) → har kadr guruhini o&#39;z katagiga → oyoq chizig&#39;i bir xil → Export As PNG <code>qahramon_idle_sheet_32x32.png</code>. Tekshirish: 800% da ko&#39;rilganda kadrlar chegaradan chiqmaydi.</p><h3 id="_3-topshiriq-yurish-animatsiyasi-sheet-o-rta" tabindex="-1">3-topshiriq. Yurish animatsiyasi sheet (o&#39;rta) <a class="header-anchor" href="#_3-topshiriq-yurish-animatsiyasi-sheet-o-rta" aria-label="Permalink to &quot;3-topshiriq. Yurish animatsiyasi sheet (o&#39;rta)&quot;">​</a></h3><p>Qahramon uchun 4 kadrli yurish animatsiyasini chizing (oyoqlar: o&#39;ng oldinda → birga → chap oldinda → birga) va 128×32 px sheet qilib yig&#39;ing.</p><p><strong>Yechim:</strong></p><ol><li>Kadr 1: o&#39;ng oyoq oldinda, tana 1 px pastda; kadr 2: oyoqlar birga, tana asl joyda; kadr 3: chap oyoq oldinda, tana 1 px pastda; kadr 4: kadr 2 ning nusxasi (yoki biroz farqli qo&#39;l holati).</li><li>128×32 hujjat, Guide Layout Columns 4, kadrlar joylashtiriladi.</li><li>Tekshirish: Timeline&#39;da 4 kadr × 0.15 s qilib ijro etilganda qahramon «joyida yuradi», oyoq chizig&#39;i sakramaydi.</li><li>Export: <code>qahramon_yurish_sheet_32x32.png</code>.</li></ol><h3 id="_4-topshiriq-obyektlar-atlasi-va-optimallashtirish-qiyin" tabindex="-1">4-topshiriq. Obyektlar atlasi va optimallashtirish (qiyin) <a class="header-anchor" href="#_4-topshiriq-obyektlar-atlasi-va-optimallashtirish-qiyin" aria-label="Permalink to &quot;4-topshiriq. Obyektlar atlasi va optimallashtirish (qiyin)&quot;">​</a></h3><p>64×64 px atlasga (16×16 kataklar) kamida 6 ta obyekt va ikonka joylashtiring, o&#39;xshashlarini bir qatorga qo&#39;ying, faylni PNG qilib saqlang va alohida PNG fayllar yig&#39;indisi bilan hajmini solishtiring.</p><p><strong>Yechim:</strong></p><ul><li>1-qator: tanga (2 kadr: oddiy + yaltirash), olmos; 2-qator: qizil va moviy zelye; 3-qator: kalit, sandiq ikonkasi; 4-qator: zaxira.</li><li>Ranglar — 12-dars palitrasidan, kontur rangi bir xil.</li><li>Export As PNG <code>obyektlar_atlas_16x16.png</code>. Alohida 6 ta PNG odatda jami bir necha KB ko&#39;proq (har faylda sarlavha ma&#39;lumotlari takrorlanadi), atlas esa bitta fayl — hajm va yuklanish kamayadi. Asosiy foyda — dvijokda draw call kamayishi.</li></ul><hr>',15))]),i("div",q,[i("h2",p,[r(t,{name:"file-text"}),a[9]||(a[9]=l(" Tezkor nazorat savollari ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#tezkor-nazorat-savollari","aria-label":'Permalink to "<Icon name="file-text" /> Tezkor nazorat savollari"'},"​",-1))]),a[11]||(a[11]=o("<ol><li>Sprayt sheet nima? <ul><li><em>Javob:</em> Bir nechta sprayt yoki animatsiya kadri bitta rasm faylida to&#39;r ko&#39;rinishida.</li></ul></li><li>Nega atlas o&#39;yinni tezlashtiradi? <ul><li><em>Javob:</em> Bitta fayl yuklanadi va bir xil atlasdagi spraytlar birga chiziladi — draw call kamayadi.</li></ul></li><li>Nega barcha kataklar bir xil o&#39;lchamda bo&#39;lishi kerak? <ul><li><em>Javob:</em> Dvijok to&#39;rni avtomatik kesadi (Grid By Cell Size); har xil katak kadrlarni buzadi.</li></ul></li><li>Padding nima uchun kerak? <ul><li><em>Javob:</em> Qo&#39;shni kadr ranglari bir-biriga «oqib» kirmasligi uchun.</li></ul></li><li>Sheet qaysi formatda saqlanadi? <ul><li><em>Javob:</em> Shaffof PNG, asl o&#39;lchamda (100%).</li></ul></li></ol><hr>",2))]),i("div",c,[i("h2",f,[r(t,{name:"file-text"}),a[12]||(a[12]=l(" Keng tarqalgan xatolar va ularning oldini olish ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#keng-tarqalgan-xatolar-va-ularning-oldini-olish","aria-label":'Permalink to "<Icon name="file-text" /> Keng tarqalgan xatolar va ularning oldini olish"'},"​",-1))]),a[14]||(a[14]=o("<ul><li><strong>Kataklar har xil o&#39;lchamda:</strong> dvijok kadrlarni noto&#39;g&#39;ri kesadi — Guide Layout bilan teng to&#39;r.</li><li><strong>Tayanch nuqta suriladi:</strong> animatsiyada qahramon «sakraydi» — oyoq chizig&#39;ini barcha kadrlarda tekshiring.</li><li><strong>Kadrlar orasida padding yo&#39;q:</strong> chetlarda qo&#39;shni kadr rangi ko&#39;rinadi — 1–2 px oraliq yoki toza shaffof chet.</li><li><strong>JPG eksport:</strong> fon oq bo&#39;lib qoladi — faqat PNG.</li><li><strong>800% kattalashtirilgan sheetni dvijokka berish:</strong> fayl og&#39;ir — dvijokka 100%.</li><li><strong>Nomda kadr o&#39;lchami yo&#39;q:</strong> jamoadosh qanday kesishni bilmaydi — <code>_32x32</code> qo&#39;shing.</li></ul>",1))])])}const N=s(h,[["render",_]]);export{S as __pageData,N as default};
